    "CREATE OR REPLACE FUNCTION portal_link_oeffnen(p_link text, p_anschluss text, p_sitzung text, p_neue_sitzung text)\nRETURNS TABLE (ergebnis text, email_anzeige text, minuten integer) LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, @SCHEMA@, pg_temp AS $$\n#variable_conflict use_column\nDECLARE\n  v_rest integer;\n  v_zugang integer;\n  v_anzeige text;\n  v_grund text;\n  v_sitzung integer;\nBEGIN\n  IF NOT (portal_hash_gueltig(p_link) AND portal_hash_gueltig(p_anschluss)) THEN\n    RETURN QUERY SELECT 'ungueltig'::text, NULL::text, NULL::integer;\n    RETURN;\n  END IF;\n  v_rest := portal_bremse('link:a:' || p_anschluss, 30, interval '1 hour');\n  IF v_rest > 0 THEN\n    PERFORM portal_protokoll(NULL, NULL, 'link_geoeffnet', 'bremse');\n    RETURN QUERY SELECT 'bremse'::text, NULL::text, v_rest;\n    RETURN;\n  END IF;\n  SELECT z.id, z.email_anzeige INTO v_zugang, v_anzeige FROM portal_zugaenge z WHERE z.link_sha256 = p_link FOR NO KEY UPDATE;\n  IF v_zugang IS NULL THEN\n    PERFORM portal_protokoll(NULL, NULL, 'link_geoeffnet', 'unbekannt');\n    RETURN QUERY SELECT 'ungueltig'::text, NULL::text, NULL::integer;\n    RETURN;\n  END IF;\n  v_grund := portal_zugang_grund(v_zugang);\n  IF v_grund IS NOT NULL THEN\n    PERFORM portal_protokoll(v_zugang, NULL, 'link_geoeffnet', v_grund);\n    RETURN QUERY SELECT 'ungueltig'::text, NULL::text, NULL::integer;\n    RETURN;\n  END IF;\n  SELECT s.id INTO v_sitzung FROM portal_sitzungen s WHERE s.id = portal_sitzung_id(p_sitzung, true) AND s.zugang_id = v_zugang;\n  IF v_sitzung IS NOT NULL THEN\n    PERFORM portal_protokoll(v_zugang, v_sitzung, 'link_geoeffnet', 'angemeldet');\n    RETURN QUERY SELECT 'angemeldet'::text, NULL::text, NULL::integer;\n    RETURN;\n  END IF;\n  IF NOT portal_hash_gueltig(p_neue_sitzung) THEN\n    RETURN QUERY SELECT 'ungueltig'::text, NULL::text, NULL::integer;\n    RETURN;\n  END IF;\n  BEGIN\n    INSERT INTO portal_sitzungen (zugang_id, wert_sha256, angelegt_am, laeuft_ab)\n      VALUES (v_zugang, p_neue_sitzung, portal_jetzt(), portal_jetzt() + interval '15 minutes') RETURNING id INTO v_sitzung;\n  EXCEPTION WHEN unique_violation THEN\n    RETURN QUERY SELECT 'ungueltig'::text, NULL::text, NULL::integer;\n    RETURN;\n  END;\n  PERFORM portal_protokoll(v_zugang, v_sitzung, 'link_geoeffnet', 'code_noetig');\n  RETURN QUERY SELECT 'code_noetig'::text, v_anzeige, NULL::integer;\nEND\n$$",
    "CREATE OR REPLACE FUNCTION portal_code_anfordern(p_sitzung text, p_anschluss text)\nRETURNS TABLE (ergebnis text, minuten integer) LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, @SCHEMA@, pg_temp AS $$\n#variable_conflict use_column\nDECLARE\n  v_zugang integer;\n  v_sitzung integer;\n  v_rest integer;\nBEGIN\n  IF NOT portal_hash_gueltig(p_anschluss) THEN\n    RETURN QUERY SELECT 'ungueltig'::text, NULL::integer;\n    RETURN;\n  END IF;\n  SELECT s.zugang_id INTO v_zugang FROM portal_sitzungen s WHERE s.id = portal_sitzung_id(p_sitzung, false);\n  IF v_zugang IS NULL THEN\n    RETURN QUERY SELECT 'ungueltig'::text, NULL::integer;\n    RETURN;\n  END IF;\n  PERFORM 1 FROM portal_zugaenge z WHERE z.id = v_zugang FOR NO KEY UPDATE;\n  SELECT s.id INTO v_sitzung FROM portal_sitzungen s WHERE s.id = portal_sitzung_id(p_sitzung, false) FOR UPDATE;\n  IF v_sitzung IS NULL THEN\n    RETURN QUERY SELECT 'ungueltig'::text, NULL::integer;\n    RETURN;\n  END IF;\n  IF EXISTS (SELECT 1 FROM portal_post p WHERE p.sitzung_id = v_sitzung AND p.angefordert_am > portal_jetzt() - interval '60 seconds') THEN\n    RETURN QUERY SELECT 'bremse'::text, 1;\n    RETURN;\n  END IF;\n  v_rest := greatest(\n    portal_bremse('code:z:' || v_zugang, 3, interval '15 minutes'),\n    portal_bremse('code:zt:' || v_zugang, 10, interval '1 day'),\n    portal_bremse('code:a:' || p_anschluss, 10, interval '1 hour'),\n    portal_bremse('code:g', 200, interval '1 hour'));\n  IF v_rest > 0 THEN\n    PERFORM portal_protokoll(v_zugang, v_sitzung, 'code_angefordert', 'bremse');\n    RETURN QUERY SELECT 'bremse'::text, v_rest;\n    RETURN;\n  END IF;\n  INSERT INTO portal_post (art, zugang_id, sitzung_id, angefordert_am, status) VALUES ('code', v_zugang, v_sitzung, portal_jetzt(), 'wartet');\n  PERFORM pg_notify('portal_post', '');\n  PERFORM portal_protokoll(v_zugang, v_sitzung, 'code_angefordert', 'ok');\n  RETURN QUERY SELECT 'angefordert'::text, NULL::integer;\nEND\n$$",
