    "CREATE OR REPLACE FUNCTION portal_code_pruefen(p_sitzung text, p_pruefwert text, p_neue_sitzung text, p_anschluss text)\nRETURNS TABLE (ergebnis text, zahl integer) LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, @SCHEMA@, pg_temp AS $$\n#variable_conflict use_column\nDECLARE\n  v_rest integer;\n  v_zugang integer;\n  v_sitzung integer;\n  v_code integer;\n  v_wert text;\n  v_gueltig timestamp;\n  v_versuche integer;\nBEGIN\n  IF NOT (portal_hash_gueltig(p_pruefwert) AND portal_hash_gueltig(p_neue_sitzung) AND portal_hash_gueltig(p_anschluss)) THEN\n    RETURN QUERY SELECT 'ungueltig'::text, NULL::integer;\n    RETURN;\n  END IF;\n  v_rest := portal_bremse('pruefen:a:' || p_anschluss, 30, interval '1 hour');\n  IF v_rest > 0 THEN\n    PERFORM portal_protokoll(NULL, NULL, 'angemeldet', 'bremse');\n    RETURN QUERY SELECT 'bremse'::text, v_rest;\n    RETURN;\n  END IF;\n  SELECT s.zugang_id INTO v_zugang FROM portal_sitzungen s WHERE s.id = portal_sitzung_id(p_sitzung, false);\n  IF v_zugang IS NULL THEN\n    RETURN QUERY SELECT 'ungueltig'::text, NULL::integer;\n    RETURN;\n  END IF;\n  PERFORM 1 FROM portal_zugaenge z WHERE z.id = v_zugang FOR NO KEY UPDATE;\n  SELECT s.id INTO v_sitzung FROM portal_sitzungen s WHERE s.id = portal_sitzung_id(p_sitzung, false) FOR UPDATE;\n  IF v_sitzung IS NULL THEN\n    RETURN QUERY SELECT 'ungueltig'::text, NULL::integer;\n    RETURN;\n  END IF;\n  SELECT c.id, c.pruefwert, c.gueltig_bis, c.versuche INTO v_code, v_wert, v_gueltig, v_versuche FROM portal_codes c\n    WHERE c.sitzung_id = v_sitzung AND c.verbraucht_am IS NULL AND c.ersetzt_am IS NULL ORDER BY c.id DESC LIMIT 1 FOR UPDATE;\n  IF v_code IS NULL OR v_gueltig <= portal_jetzt() OR v_versuche >= 5 THEN\n    PERFORM portal_protokoll(v_zugang, v_sitzung, 'code_abgelaufen', 'ungueltig');\n    RETURN QUERY SELECT 'neu_anfordern'::text, NULL::integer;\n    RETURN;\n  END IF;\n  UPDATE portal_codes SET versuche = versuche + 1 WHERE id = v_code;\n  IF v_wert <> p_pruefwert THEN\n    PERFORM portal_protokoll(v_zugang, v_sitzung, 'code_falsch', 'ungueltig');\n    RETURN QUERY SELECT 'falsch'::text, 5 - (v_versuche + 1);\n    RETURN;\n  END IF;\n  BEGIN\n    UPDATE portal_sitzungen SET bestaetigt_am = portal_jetzt(), wert_sha256 = p_neue_sitzung, zuletzt_am = portal_jetzt(),\n      laeuft_ab = portal_jetzt() + interval '30 days' WHERE id = v_sitzung;\n  EXCEPTION WHEN unique_violation THEN\n    RETURN QUERY SELECT 'ungueltig'::text, NULL::integer;\n    RETURN;\n  END;\n  UPDATE portal_codes SET verbraucht_am = portal_jetzt() WHERE id = v_code;\n  UPDATE portal_zugaenge SET zuletzt_genutzt_am = portal_jetzt() WHERE id = v_zugang;\n  PERFORM portal_protokoll(v_zugang, v_sitzung, 'angemeldet', 'ok');\n  RETURN QUERY SELECT 'angemeldet'::text, NULL::integer;\nEND\n$$",
