    "CREATE OR REPLACE FUNCTION portal_sitzung_weiter(p_sitzung text) RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, @SCHEMA@, pg_temp AS $$\nDECLARE\n  v_zugang integer;\n  v_sitzung integer;\n  v_zuletzt timestamp;\nBEGIN\n  SELECT s.zugang_id INTO v_zugang FROM portal_sitzungen s WHERE s.id = portal_sitzung_id(p_sitzung, true);\n  IF v_zugang IS NULL THEN\n    RETURN 'ungueltig';\n  END IF;\n  PERFORM 1 FROM portal_zugaenge z WHERE z.id = v_zugang FOR NO KEY UPDATE;\n  SELECT s.id, s.zuletzt_am INTO v_sitzung, v_zuletzt FROM portal_sitzungen s WHERE s.id = portal_sitzung_id(p_sitzung, true) FOR UPDATE;\n  IF v_sitzung IS NULL THEN\n    RETURN 'ungueltig';\n  END IF;\n  IF v_zuletzt IS NOT NULL AND v_zuletzt > portal_jetzt() - interval '1 hour' THEN\n    RETURN 'gueltig';\n  END IF;\n  UPDATE portal_sitzungen SET zuletzt_am = portal_jetzt(), laeuft_ab = portal_jetzt() + interval '30 days' WHERE id = v_sitzung;\n  UPDATE portal_zugaenge SET zuletzt_genutzt_am = portal_jetzt() WHERE id = v_zugang;\n  PERFORM portal_protokoll(v_zugang, v_sitzung, 'verlaengert', 'ok');\n  RETURN 'verlaengert';\nEND\n$$",
    "CREATE OR REPLACE FUNCTION portal_abmelden(p_sitzung text, p_ueberall boolean) RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, @SCHEMA@, pg_temp AS $$\nDECLARE\n  v_zugang integer;\n  v_sitzung integer;\nBEGIN\n  IF NOT portal_hash_gueltig(p_sitzung) THEN\n    RETURN 'ungueltig';\n  END IF;\n  SELECT s.zugang_id INTO v_zugang FROM portal_sitzungen s WHERE s.wert_sha256 = p_sitzung AND s.beendet_am IS NULL;\n  IF v_zugang IS NULL THEN\n    RETURN 'ungueltig';\n  END IF;\n  PERFORM 1 FROM portal_zugaenge z WHERE z.id = v_zugang FOR NO KEY UPDATE;\n  SELECT s.id INTO v_sitzung FROM portal_sitzungen s WHERE s.wert_sha256 = p_sitzung AND s.beendet_am IS NULL FOR UPDATE;\n  IF v_sitzung IS NULL THEN\n    RETURN 'ungueltig';\n  END IF;\n  IF p_ueberall THEN\n    IF portal_sitzung_id(p_sitzung, true) IS NULL THEN\n      RETURN 'ungueltig';\n    END IF;\n    UPDATE portal_sitzungen SET beendet_am = portal_jetzt(), beendet_grund = 'ueberall' WHERE zugang_id = v_zugang AND beendet_am IS NULL;\n    PERFORM portal_protokoll(v_zugang, v_sitzung, 'ueberall_abgemeldet', 'ok');\n  ELSE\n    UPDATE portal_sitzungen SET beendet_am = portal_jetzt(), beendet_grund = 'abgemeldet' WHERE id = v_sitzung;\n    PERFORM portal_protokoll(v_zugang, v_sitzung, 'abgemeldet', 'ok');\n  END IF;\n  RETURN 'abgemeldet';\nEND\n$$",
